-- 020_road_network_osm.sql
-- The road network on OpenStreetMap: provenance of the ROUTING geometry
-- (WP-20, wave 3, contract C-K basis 'osm').
--
-- SCHEMA ONLY, additive, idempotent: safe on fresh installs (before the
-- seed) and on the ledgered live install.  Adds three nullable columns and
-- touches no row: the network itself is converted by the data step
-- services/corridor-store/seed/reanchor_osm_network.sql (generated by
-- scripts/gen_osm_network.py, (c) OpenStreetMap contributors, ODbL 1.0),
-- which scripts/veer_up.sh seed() applies after this migration.
--
--   1. corridor.road_segments.geom_source - how geom (the line every
--      planner routes, costs and attributes on) was drawn: 'osm' = the path
--      along the OpenStreetMap way(s) between the segment's two junction
--      nodes, 'schematic' = a hand-placed seed polyline.  NULL = not
--      recorded (a store the data step has not reached): treated as
--      schematic.  The oracle's spatial router serves geometry_basis 'osm'
--      for a segment whose geom_source is 'osm' and that carries no
--      migration 015 display line.
--   2. corridor.road_segments.geom_meta - geom's provenance: the OSM way
--      ids in path order, the osm_base timestamp, the OSM names along it
--      and the validation metrics (length, Hausdorff distance to the OSM
--      centreline).
--   3. corridor.junctions.osm_node_id - the OpenStreetMap node the junction
--      sits on (NULL for a junction placed any other way).
--
-- Ethics rails (C6): road geometry provenance only - no person, plate,
-- camera or frame column.
--
-- Grammar constraint (007 header): consumed by naive ';'-splitters - no
-- ';' inside string literals, no dollar-quoted bodies, no block comments.
-- Re-applying is a no-op: ADD COLUMN IF NOT EXISTS, and the guarded DROP
-- removes the CHECK the previous apply added before the ADD recreates it.

ALTER TABLE corridor.road_segments
    ADD COLUMN IF NOT EXISTS geom_source TEXT;

ALTER TABLE corridor.road_segments
    DROP CONSTRAINT IF EXISTS road_segments_geom_source_check;

ALTER TABLE corridor.road_segments
    ADD CONSTRAINT road_segments_geom_source_check CHECK (
        geom_source IS NULL OR geom_source IN ('schematic', 'osm')
    );

ALTER TABLE corridor.road_segments
    ADD COLUMN IF NOT EXISTS geom_meta JSONB;

ALTER TABLE corridor.junctions
    ADD COLUMN IF NOT EXISTS osm_node_id BIGINT;

COMMENT ON COLUMN corridor.road_segments.geom_source IS
    'how geom was drawn: osm (OpenStreetMap way path) | schematic (hand-placed) - NULL is schematic';

COMMENT ON COLUMN corridor.road_segments.geom_meta IS
    'geom provenance: OSM way ids, osm_base timestamp, names, validation metrics (ODbL 1.0)';

COMMENT ON COLUMN corridor.junctions.osm_node_id IS
    'the OpenStreetMap node the junction sits on (ODbL 1.0) - NULL when placed otherwise';
